const resp = $input.first().json;
const pedido = $('Armar pedido a Claude').first().json;

const textoCrudo = (resp.content || [])
  .filter((b) => b.type === 'text')
  .map((b) => b.text)
  .join('\n');

const sacar = (tag) => {
  const m = textoCrudo.match(new RegExp(`<${tag}>([\\s\\S]*?)</${tag}>`));
  return m ? m[1].trim() : null;
};

const razonamiento = sacar('razonamiento');
const respuestaCruda = sacar('respuesta');
const motivos = [];
let datos = null;
let pieza = null;

if (resp.stop_reason !== 'end_turn') {
  motivos.push(`La respuesta no terminó bien (stop_reason: ${resp.stop_reason})`);
}
if (!respuestaCruda) {
  motivos.push('Falta el bloque <respuesta>');
} else {
  try {
    datos = JSON.parse(respuestaCruda);
  } catch (e) {
    motivos.push('El JSON de la respuesta no es válido: ' + e.message);
  }
}

if (datos) {
  const lista = datos.textos_piezas && datos.textos_piezas.piezas;
  if (!Array.isArray(lista) || lista.length !== 1) {
    motivos.push('Se esperaba exactamente 1 pieza en la respuesta');
  } else {
    pieza = lista[0];
    if (pieza.pieza_id !== pedido.pieza_id) {
      motivos.push(`El pieza_id devuelto (${pieza.pieza_id}) no coincide con ${pedido.pieza_id}`);
    }
    if (pieza.plantilla && (!Array.isArray(pieza.slides) || pieza.slides.length === 0)) {
      motivos.push('La pieza tiene plantilla pero no tiene slides');
    }
    for (const s of pieza.slides || []) {
      for (const [campo, valor] of Object.entries(s)) {
        if (typeof valor === 'string' && valor.trim() === '') {
          motivos.push(`Slide "${s.tipo}": el campo "${campo}" está vacío`);
        }
      }
    }
    if (pieza.copy) {
      const hook = String(pieza.copy).split('\n')[0];
      if (hook.length > 125) {
        motivos.push(`El hook del copy tiene ${hook.length} caracteres (máximo 125)`);
      }
    }
  }
}

const lista = (a) => (Array.isArray(a) ? a.map((x) => `- ${x}`).join('\n') : '');
const usage = resp.usage || {};
// Tarifas en USD por millón de tokens (confirmar en la página oficial de precios)
const TARIFA = { entrada: 2, escritura_cache: 2.5, lectura_cache: 0.10, salida: 10 };
const costo = (
  (usage.input_tokens || 0) * TARIFA.entrada +
  (usage.cache_creation_input_tokens || 0) * TARIFA.escritura_cache +
  (usage.cache_read_input_tokens || 0) * TARIFA.lectura_cache +
  (usage.output_tokens || 0) * TARIFA.salida
) / 1e6;

return [{
  json: {
    ok: motivos.length === 0,
    motivo: motivos.join(' | '),
    record_id: pedido.record_id,
    pieza_id: pedido.pieza_id,
    razonamiento: razonamiento || '',
    textos: pieza ? JSON.stringify(pieza, null, 2) : (respuestaCruda || textoCrudo),
    requiere_revision_tecnica: !!(pieza && pieza.requiere_revision_tecnica),
    puntos_a_verificar: pieza ? lista(pieza.puntos_a_verificar) : '',
    datos_a_confirmar: pieza ? lista(pieza.datos_a_confirmar) : '',
    problemas_detectados: datos && datos.textos_piezas ? lista(datos.textos_piezas.problemas_detectados) : '',
    tokens_entrada: usage.input_tokens,
    tokens_cache_escritura: usage.cache_creation_input_tokens,
    tokens_cache_lectura: usage.cache_read_input_tokens,
    tokens_salida: usage.output_tokens,
        costo_usd: Number(costo.toFixed(4)),
  },
}];

const fila = $('armar idea semilla').first().json;

let etapa = 'Cargar contexto del cliente';
try {
  $('Armar pedido a Claude').first();
  etapa = 'Llamar a Claude';
} catch (e) {}

const err = $json.error;
const mensaje = (
  typeof err === 'string'
    ? err
    : (err && (err.message || err.description)) || JSON.stringify($json)
).slice(0, 500);

return [{
  json: {
    record_id: fila.record_id,
    pieza_id: fila.pieza_id,
    etapa,
    mensaje,
    cuando: new Date().toISOString(),
  },
}];
